import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, CircleGeometry } = ctx.THREE;
  const root = new Group();
  const resources = [];
  const timelines = [];
  let disposed = false;

  const spec = config.intent?.visualSpec ?? {};
  const palette = spec.colors ?? {};
  const ink = palette.ink ?? '#16161d';
  const paper = palette.paper ?? '#e8ecf2';
  const accent = palette.accent ?? '#ff2a38';
  const surface = palette.surface ?? '#0b0b10';

  const hexToRgb = (hex) => {
    const value = String(hex).replace('#', '');
    const normalized = value.length === 3
      ? value.split('').map((v) => v + v).join('')
      : value;
    return [
      parseInt(normalized.slice(0, 2), 16) / 255,
      parseInt(normalized.slice(2, 4), 16) / 255,
      parseInt(normalized.slice(4, 6), 16) / 255
    ];
  };

  const nodeColor = (hex) => {
    const [r, g, b] = hexToRgb(hex);
    return vec3(r, g, b);
  };

  const backdropMaterial = new MeshBasicNodeMaterial({
    depthWrite: false,
    toneMapped: false
  });
  backdropMaterial.colorNode = mix(
    nodeColor(surface),
    mix(nodeColor(ink), nodeColor(surface), smoothstep(0.15, 0.85, uv().y)),
    smoothstep(0.0, 1.0, uv().y)
  );

  const backdrop = new Mesh(new PlaneGeometry(7, 6), backdropMaterial);
  backdrop.position.z = -2.5;
  root.add(backdrop);
  resources.push(backdrop.geometry, backdrop.material);

  const shadowMaterial = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.48,
    depthWrite: false,
    toneMapped: false
  });
  shadowMaterial.colorNode = nodeColor('#000000');

  const shadow = new Mesh(new CircleGeometry(1.8, 64), shadowMaterial);
  shadow.scale.set(1.55, 0.34, 1);
  shadow.position.set(0, -1.2, -0.08);
  root.add(shadow);
  resources.push(shadow.geometry, shadow.material);

  const cardMaterial = new MeshBasicNodeMaterial({
    toneMapped: false
  });
  cardMaterial.colorNode = mix(
    nodeColor(surface),
    nodeColor(ink),
    smoothstep(0.0, 1.0, uv().y)
  );

  const card = new Mesh(new PlaneGeometry(3.8, 2.35), cardMaterial);
  card.position.z = 0;
  root.add(card);
  resources.push(card.geometry, card.material);

  const edgeMaterial = new MeshBasicNodeMaterial({
    toneMapped: false
  });
  edgeMaterial.colorNode = nodeColor(paper);

  const accentMaterial = new MeshBasicNodeMaterial({
    toneMapped: false
  });
  accentMaterial.colorNode = nodeColor(accent);

  const topEdge = new Mesh(new PlaneGeometry(3.58, 0.018), edgeMaterial);
  topEdge.position.set(0, 1.08, 0.025);

  const bottomEdge = new Mesh(new PlaneGeometry(3.58, 0.018), edgeMaterial);
  bottomEdge.position.set(0, -1.08, 0.025);

  const leftEdge = new Mesh(new PlaneGeometry(0.018, 2.16), edgeMaterial);
  leftEdge.position.set(-1.79, 0, 0.025);

  const rightEdge = new Mesh(new PlaneGeometry(0.018, 2.16), edgeMaterial);
  rightEdge.position.set(1.79, 0, 0.025);

  const signalRail = new Mesh(new PlaneGeometry(0.055, 1.56), accentMaterial);
  signalRail.position.set(-1.48, -0.03, 0.035);

  root.add(topEdge, bottomEdge, leftEdge, rightEdge, signalRail);
  resources.push(
    topEdge.geometry,
    bottomEdge.geometry,
    leftEdge.geometry,
    rightEdge.geometry,
    signalRail.geometry,
    edgeMaterial,
    accentMaterial
  );

  const imageUrl = config.imageUrl ?? spec.imageUrl;
  if (imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      if (disposed) return;
      if (ctx.THREE.SRGBColorSpace) tex.colorSpace = ctx.THREE.SRGBColorSpace;
      cardMaterial.colorNode = mix(
        mix(nodeColor(surface), nodeColor(ink), smoothstep(0.0, 1.0, uv().y)),
        texture(tex),
        0.24
      );
      cardMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string' || !ctx.fontAtlas?.createText) continue;
    const label = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize,
      color: item.color ?? paper,
      align: item.align ?? 'left',
      maxWidthPx: item.maxWidthPx,
      letterSpacingPx: item.typography?.letterSpacingPx
    });
    label.position.set(
      item.position?.x ?? -1.25,
      item.position?.y ?? 0,
      item.position?.z ?? 0.05
    );
    root.add(label);
  }

  const primitiveCleanups = [];
  for (const primitive of config.cinematicPrimitives ?? []) {
    const apply = ctx.primitives?.[primitive.name];
    if (typeof apply !== 'function') continue;
    const result = apply(root, primitive.params);
    if (result?.timeline) timelines.push(result.timeline);
    if (typeof result?.cleanup === 'function') primitiveCleanups.push(result.cleanup);
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      if (timeline?.kill) timeline.kill();
    }

    for (const cleanup of primitiveCleanups) cleanup();

    root.traverse((object) => {
      if (object.geometry?.dispose) object.geometry.dispose();
      if (object.material) {
        const materials = Array.isArray(object.material)
          ? object.material
          : [object.material];
        for (const material of materials) {
          if (material?.dispose) material.dispose();
        }
      }
    });
  };

  return root;
}
